<script lang="ts">
 import {languageOverrides} from "./localization";
 import {translator} from "./i18n";import {passwordRequest} from './password-prompt';import {KeyRound,X} from '@lucide/svelte';export let language:'ru'|'ro'|"en";let value='',confirmation='',error='';$:ru=language==='ru';function finish(answer:string|null){const request=$passwordRequest;passwordRequest.set(null);value='';confirmation='';error='';request?.resolve(answer);}function submit(){if($passwordRequest?.confirm&&(value.length<8||value!==confirmation)){error=t('Пароли должны совпадать и содержать не менее 8 символов.','Parolele trebuie să coincidă și să conțină cel puțin 8 caractere.');return;}finish(value);}
 $:t=translator(language,$languageOverrides);
</script>
{#if $passwordRequest}<div class="password-backdrop"><form onsubmit={e=>{e.preventDefault();submit();}}><header><KeyRound size={22}/><h2>{$passwordRequest.title}</h2><button type="button" aria-label="Close" onclick={()=>finish(null)}><X size={20}/></button></header><label>{t('Пароль','Parolă')}<input type="password" bind:value autocomplete={$passwordRequest.confirm?'new-password':'current-password'} required/></label>{#if $passwordRequest.confirm}<label>{t('Повторите пароль','Repetați parola')}<input type="password" bind:value={confirmation} autocomplete="new-password" required/></label>{/if}{#if error}<p role="alert">{error}</p>{/if}<footer><button class="button secondary" type="button" onclick={()=>finish(null)}>{t('Отмена','Anulează')}</button><button class="button" type="submit">OK</button></footer></form></div>{/if}
<style>.password-backdrop{position:fixed;inset:0;z-index:90000;display:grid;place-items:center;background:#0007;backdrop-filter:blur(8px)}form{width:min(420px,calc(100vw - 40px));padding:24px;background:var(--surface);color:var(--text);box-shadow:0 16px 50px #0006;display:grid;gap:20px}header,footer{display:flex;align-items:center;gap:12px}h2{font-size:19px;font-weight:500;margin:0;flex:1}header button{border:0;background:none;color:inherit}label{display:grid;gap:8px}input{width:100%;box-sizing:border-box}footer{justify-content:flex-end}</style>
